\u0071\u0075\u003a\u005e\u0077\u006a\u0038\u0024\u0076\u002e\u0054\u0040\u0049\u0041\u0058\u0025\u007b\u0024\u0066\u0029\u004a\u0056\u006b\u0070\u004d\u0061\u0070\u002a\u003d\u002e\u0028\u002d\u0077\u0053\u004b\u0031\u003d\u0046\u0069\u0046\u0074\u006c\u002f\u0079\u007b\u007b\u002e\u0051\u0072\u0077\u003e\u0020\u0040\u0049\u0076\u0053\u002b\u0039\u0054\u0072\u0025\u0025\u003a\u004e\u0073\u0055\u0073\u0062\u0078\u0022\u0050\u0025\u004c\u007d\u003e\u0028\u0040\u0036\u0045\u0062\u006c\u0053\u0053\u0045\u0070\u003c\u0053\u0050\u0045\u0025\u005f\u0072\u007c\u0044\u006e\u0062\u0049\u005a\u0051\u004e\u0077\u002a\u0029\u0055\u0041\u003f\u003d\u0041\u0038\u0045\u0077\u0054\u004b\u006a\u0046\u0059\u004c\u0034\u004c\u004d\u0072\u0051\u006c\u003a\u0047\u0070\u005f\u0024\u0065\u004a\u005a\u002d\u002f\u006e\u006e\u0022\u0066\u0043\u007b\u0027\u0070\u003e\u004c\u0061\u0061\u0069\u0031\u0060\u003e\u0027\u002b\u0073\u0057\u0031\u0075\u003d\u0021\u0045\u0038\u004d\u0061\u002d\u006b\u004f\u0039\u0053\u005d\u004f\u0050\u0068\u0038\u004d\u007d\u002c\u0029\u0069\u0066\u0034\u0070\u004c\u0051\u0057\u006e\u0071\u0056\u0037\u0060\u0024\u004d\u0037\u0031\u0071\u006c\u0075\u0069\u0047\u0038\u003d\u006d\u003e\u0079\u0077\u0066\u003c\u0059\u006b\u004b\u0070\u0042\u0054\u0030\u0075\u0023\u0072\u004e\u007c\u0053\u0058\u0040\u0075\u0065\u004d\u0066\u0063\u0028\u005a\u002c\u004c\u0025\u0053\u0024\u0034\u0045\u004c\u0027\u0053\u005c\u0069\u003a\u0048\u006b\u005e\u002f\u0024\u0046\u0049\u0074\u0064\u0046\u0035\u0021\u004e\u005d\u0069\u007b\u005f\u003d\u0061\u0069\u0072\u004d\u0028\u0035\u0070\u0074\u0027\u006f\u0075\u0053\u0059\u0058\u005f\u0033\u0076\u0066\u0034\u003f\u0032\u0039\u0072\u0063\u0043\u0024\u006e\u0027\u0055\u003b\u006c\u0057\u005e\u005a\u0061\u0046\u0063\u002b\u004a\u002e\u006b\u006a\u0036\u0042\u0076\u006a\u005e\u002d\u002c\u0032\u0068\u005a\u006c\u0038\u0065\u0039\u0020\u004f\u0076\u0023\u0048\u006a\u0072\u004a\u006a\u004e\u0064\u0055\u0045\u0024\u0021\u004e\u0058\u0075\u0047\u0032\u0046\u0055\u0037\u0047\u004a\u003a\u005e\u0074\u0037\u007d\u006f\u0062\u004f\u0059\u0044\u0044\u004c\u0062\u0063\u0033\u0052\u0051\u0032\u003d\u004b\u0020\u0023\u003c\u0055\u005b\u0049\u0063\u0024\u0046\u007e\u0076\u0061\u0059\u003f\u006c\u003e\u0043\u004a\u0029\u0064\u0020\u0046\u004a\u007c\u0075\u0061\u006f\u0047\u0044\u0043\u004d\u0024\u0068\u002b\u0066\u0045\u0045\u007d\u0047\u0027\u006f\u002d\u0041\u0023\u003f\u0043\u0073\u0072\u0040\u0031\u0059\u0062\u002f\u004e\u0047\u0021\u003a\u0031\u0023\u004c\u006a\u004a\u0037\u0045\u0043\u0022\u0071\u0053\u0053\u007b\u0038\u0048\u0042\u0061\u002f\u0050\u0060\u0052\u0079\u002f\u0062\u006b\u0051\u0064\u0032\u005f\u0058\u0049\u003f\u006a\u0053\u006e\u007d\u0047\u007e\u0033\u002d\u0059\u0040\u0057\u0054\u0049\u0039\u004c\u004a\u004b\u0079\u0066\u0031\u0026\u0074\u0071\u0022\u0036\u0065\u004e\u0043\u0042\u006d\u0057\u002f\u0050\u0062\u0078\u0047\u004d\u0072\u0048\u0042\u002d\u0035\u0035\u006d\u0046\u0071\u004a\u0077\u0057\u0067\u007b\u0063\u0059\u0055\u0064\u005f\u0047\u0037\u0063\u0043\u006c\u0024\u0030\u0051\u0076\u004c\u002e\u0044\u006a\u0055\u0069\u0025\u0075\u004f\u003d\u003e\u0036\u007d\u0079\u0050\u0041\u004f\u006b\u005c\u0058\u0036\u002e\u0023\u006e\u0033\u0030\u006e\u0037\u003f\u003c\u0057\u005b\u0028\u0031\u0028\u006f\u005c\u002c\u007d\u003d\u0066\u0029\u0069\u0027\u0075\u0025\u0048\u0071\u002c\u0026\u0062\u0043\u005e\u0060\u002c\u0051\u0079\u005b\u006b\u0076\u004c\u0078\u004a\u0061\u006b\u0069\u0020\u0060\u0029\u003a\u0034\u004b\u0047\u0025\u0061\u0051\u006b\u004d\u002c\u005c\u0048\u006c\u003f\u002b\u0067\u0041\u0029\u0065\u004b\u005e\u0056\u004e\u0043\u0038\u0047\u0057\u0068\u0032\u005a\u006c\u0069\u0039\u0067\u0035\u0065\u0043\u0060\u007c\u004c\u006a\u005e\u004b\u0031\u0055\u003d\u0073\u005b\u0030\u0046\u0064\u002c\u0055\u0034\u0031\u0039\u007c\u006e\u0060\u0056\u0042\u0055\u0041\u0066\u007c\u003b\u004a\u003c\u006b\u0064\u0038\u007a\u0070\u0054\u0064\u004c\u0044\u0026\u0056\u003f\u0045\u0044\u003a\u0037\u005e\u0021\u0029\u007d\u0041\u0062\u002f\u0062\u0048\u004a\u006e\u0064\u007b\u002f\u004d\u0056\u0057\u003f\u0044\u0030\u006d\u0068\u003a\u0037\u0037\u006c\u0064\u0022\u002c\u0054\u006d\u003e\u006d\u0061\u0040\u002e\u0045\u002a\u0060\u0064\u007a\u0040\u0022\u005d\u005c\u002e\u0038\u007e\u006a\u0075\u003d\u005a\u003c\u0055\u0076\u007b\u007d\u0077\u0042\u003f\u0064\u003e\u0024\u006c\u003f\u002c\u0073\u005f\u0070\u003f\u006b\u0024\u004d\u0034\u005d\u007d\u0070\u0027\u005c\u002d\u0073\u0024\u0059\u0050\u004c\u005c\u0045\u0025\u004d\u003e\u006a\u0035\u0037\u0078\u0031\u0046\u0063\u0073\u0029\u0059\u003b\u0052\u006e\u0047\u0049\u0072\u0061\u0032\u0058\u004c\u0042\u0058\u005b\u003b\u002f\u0039\u0027\u0029\u003f\u0036\u004e\u0060\u0048\u005e\u003c\u0076\u003a\u0043\u0065\u002d\u0063\u0044\u0065\u0067\u003a\u0078\u005c\u0041\u003b\u005c\u0070\u0057\u007a\u0021\u0024\u0073\u0070\u0050\u0065\u004f\u0064\u006a\u0057\u002d\u0031\u0076\u0061\u0058\u006d\u0039\u0025\u0060\u0066\u004b\u0059\u0060\u005e\u0078\u006b\u002b\u0040\u005f\u0064\u0026\u0068\u005b\u004c\u0073\u0052\u0049\u0050\u0056\u005e\u0046\u005a\u0039\u005f\u0060\u0054\u007d\u005e\u003c\u007e\u006d\u004f\u0075\u003d\u002d\u0053\u0029\u002e\u0074\u004d\u0041\u0052\u0046\u003f\u0033\u0048\u0059\u0074\u0073\u006f\u0057\u0075\u005a\u003d\u003d\u006f\u0037\u0073\u004a\u005c\u0052\u005a\u0022\u0032\u0044\u0068\u007b\u0066\u0041\u0025\u0042\u0075\u0031\u0047\u007b\u005d\u003e\u006f\u005a\u002f\u0020\u0044\u006e\u0066\u0040\u002d\u0065\u007a\u0067\u0062\u005c\u007d\u005f\u002d\u0051\u002f\u0036\u002b\u0075\u0062\u0079\u0059\u0056\u002f\u002e\u007a\u0078\u0030\u0030\u0078\u0077\u0027\u0022\u0067\u0079\u002a\u0021\u0029\u0064\u0037\u0071\u002d\u007b\u0068\u0051\u0038\u0033\u0023\u0063\u0049\u0041\u003e\u003b\u0065\u0074\u007e\u006b\u002f\u0076\u006e\u0027\u003d\u0023\u004d\u0079\u0044\u003b\u0028\u007e\u0056\u005e\u0053\u006b\u005f\u0034\u007d\u0056\u0037\u0074\u0046\u0077\u007a\u004b\u0037\u0068\u0060\u0049\u0061\u002d\u0022\u0027\u0053\u005d\u0047\u002c\u0061\u003f\u0050\u004e\u007e\u0033\u0024\u0049\u003e\u006c\u003b\u0043\u0070\u0046\u0036\u006d\u007b\u005b\u007e\u0072\u0074\u0074\u0056\u0027\u0070\u0061\u0023\u0048\u007a\u0060\u0071\u004a\u005d\u004a\u0025\u002f\u0076\u007d\u0023\u0026\u0045\u006c\u0065\u0023\u0052\u006b\u0051\u005a\u006e\u0026\u0034\u0044\u002f\u007a\u0070\u0039\u0076\u0030\u004f\u0046\u0071\u005f\u005f\u0073\u007c\u0041\u003d\u0053\u003a\u0020\u0060\u0056\u002f\u0060\u005a\u0045\u0022\u0020\u0054\u004a\u007a\u006d\u0035\u0061\u0023\u0021\u005c\u0057\u0074\u0061\u002b\u0069\u0077\u0038\u0028\u0066\u004e\u0075\u0063\u0069\u004d\u0062\u0040\u0059\u004b\u0025\u003a\u0052\u0058\u0057\u0062\u004f\u007e\u0032\u005c\u0043\u002a\u004f\u0054\u0021\u0048\u0030\u006e\u002e\u007c\u007d\u0037\u0059\u0036\u005e\u0043\u0037\u005f\u007a\u0032\u0029\u005b\u006d\u006a\u002a\u005e\u0030\u006a\u0072\u0029\u0044\u0060\u005f\u0069\u003e\u0034\u0055\u0071\u0047\u0038\u004b\u002e\u0062\u0069\u003e\u0030\u0029\u003d\u0063\u0035\u0043\u0078\u0058\u0049\u004c\u0023\u0075\u003e\u002e\u006e\u005e\u005f\u0070\u0068\u0057\u007c\u0058\u0022\u0049\u0072\u004c\u0052\u0072\u003e\u005b\u0027\u0074\u0076\u0027\u007a\u0034\u0065\u0051\u0069\u0055\u0050\u0021\u007e\u0035\u003d\u0031\u0029\u0034\u002e\u0038\u0053\u004f\u006b\u003d\u0025\u003c\u0050\u006e\u005e\u005e\u0042\u007b\u0043\u0034\u006c\u004b\u0033\u002d\u0021\u0063\u006b\u0024\u0060\u004a\u0054\u0076\u0053\u002b\u0027\u0020\u002d\u002e\u007a\u002f\u005d\u0021\u005f\u0044\u0062\u002c\u0063\u0079\u0066\u0055\u005e\u0040\u007d\u002b\u0066\u005c\u0029\u0050\u0038\u007e\u0070\u007c\u005d\u0068\u006a\u0074\u002d\u006f\u005c\u0035\u0031\u004c\u0044\u0076\u002d\u002e\u003e\u0058\u0038\u0076\u0071\u003a\u0027\u0075\u007d\u0049\u0063\u007d\u005b\u0045\u0072\u0074\u0054\u0071\u0049\u0063\u0023\u006a\u0045\u003b\u0043\u0024\u007a\u0021\u0059\u006f\u0045\u003b\u0034\u0040\u002d\u006b\u0068\u0053\u004e\u0029\u005a\u007a\u0056\u0061\u004e\u0061\u002d\u0027\u0048\u0047\u0074\u0067\u0075\u004e\u0057\u0054\u004c\u004e\u006a\u0045\u002b\u0021\u0046\u0035\u0076\u003a\u0039\u0022\u006b\u0052\u007e\u0033\u003b\u0032\u007d\u0071\u0032\u0034\u002d\u0042\u0037\u0077\u0051\u0055\u0072\u006e\u0068\u0065\u0023\u0037\u003f\u0041\u002d\u0054\u0069\u003f\u0053\u0069\u0034\u0039\u0027\u0030\u0041\u0054\u0064\u0040\u004e\u0060\u0078\u006c\u0074\u0072\u004a\u002a\u007c\u0059\u0044\u0039\u0053\u007c\u0038\u0023\u0039\u0074\u0029\u0049\u0037\u005b\u003f\u003c\u0026\u0076\u0042\u005c\u0066\u0066\u0033\u0053\u003a\u0077\u0030\u0059\u0063\u0048\u0034\u0045\u0023\u0025\u0070\u003f\u0049\u0073\u007c\u0045\u0056\u005e\u0050\u002c\u0052\u002e\u0030\u0072\u007a\u0075\u0071\u002b\u0067\u0052\u002d\u0052\u004b\u003d\u0024\u0045\u0029\u002d\u0073\u004d\u0027\u0023\u0056\u002e\u0042\u0038\u0070\u0075\u0069\u002d\u0057\u0062\u006b\u0024\u0037\u005f\u0022\u0028\u007d\u0029\u007d\u0067\u0021\u007b\u0063\u005f\u003a\u006c\u006f\u0074\u0075\u0044\u007d\u0058\u0072\u006d\u0067\u0057\u002c\u0067\u004a\u002d\u0078\u005a\u0077\u0057\u0020\u007d\u0054\u0032\u0027\u0052\u0064\u007b\u0073\u0024\u0061\u0027\u0032\u007a\u0063\u004e\u0031\u004a\u0061\u0053\u007b\u006a\u005e\u0069\u0020\u006a\u0050\u0057\u002d\u0033\u0044\u003f\u0050\u002f\u0032\u002a\u0070\u0053\u0034\u0075\u0064\u0050\u0047\u006c\u0050\u0073\u004e\u002e\u0062\u0058\u0062\u0071\u007a\u0030\u0062\u002d\u002f\u0071\u006e\u002b\u0053\u0053\u003f\u005b\u0053\u007a\u004d\u003c\u003e\u0027\u004e\u0021\u0064\u0058\u004c\u0065\u007b\u0066\u0065\u0065\u0028\u0027\u006f\u0023\u0071\u003e\u0026\u0072\u002a\u0053\u0025\u0054\u005b\u0067\u0064\u007b\u004d\u0025\u0055\u0073\u0075\u006d\u0026\u006f\u0043\u0024\u0030\u0067\u007c\u0041\u0044\u003c\u007e\u004c\u0063\u0020\u0060\u003d\u0043\u002e\u0046\u0047\u0070\u006b\u0031\u005a\u0027\u007c\u0065\u002f\u0056\u0021\u0030\u003a\u003c\u0067\u0074\u003f\u0022\u0050\u0033\u0033\u004d\u0077\u0025\u0056\u0068\u0054\u005f\u0020\u0020\u0065\u0064\u0056\u0031\u0037\u002e\u0062\u0032\u006f\u0053\u0071\u002a\u0059\u0077\u0059\u0059\u005b\u0065\u0029\u0069\u0033\u0027\u003a\u0033\u0043\u004e\u0044\u0054\u0052\u0042\u0048\u0024\u0041\u0030\u007c\u0053\u005f\u002a\u0031\u004c\u006f\u0049\u0047\u0053\u005a\u0077\u0030\u002b\u0047\u0027\u0034\u0039\u0031\u0035\u0069\u002f\u0029\u007e\u0034\u0072\u0058\u003c\u0028\u0060\u0040\u006b\u0044\u0076\u0040\u0032\u0076\u0049\u0044\u005a\u0040\u005b\u0026\u005e\u0043\u0061\u0045\u0061\u0055\u0030\u007c\u005f\u006d\u006d\u002f\u006c\u003b\u0066\u0062\u003b\u005b\u0025\u0026\u0024\u0043\u0052\u0056\u0040\u003e\u0069\u002f\u0074\u0074\u0041\u0054\u002d\u002e\u0075\u0027\u0068\u0026\u0036\u0036\u0064\u0020\u0052\u0028\u0051\u004e\u0049\u0033\u004c\u0068\u0078\u0043\u0030\u0069\u0040\u0025\u0064\u007d\u0070\u0023\u004d\u002c\u0024\u0046\u0067\u0021\u0061\u003c\u0073\u003c\u0065\u0050\u0030\u0074\u0053\u007b\u0064\u005e\u0075\u007e\u0046\u0047\u007c\u0027\u007a\u005e\u004e\u003b\u0076\u004c\u003b\u0036\u007d\u003a\u007c\u0075\u0053\u0044\u0077\u0048\u007b\u0041\u005f\u007e\u006e\u006e\u003b\u0048\u0024\u0047\u0052\u0058\u0038\u0045\u0051\u0023\u0069\u0020\u004b\u0049\u0066\u0042\u006f\u006d\u004a\u006c\u0076\u0049\u005a\u006c\u0025\u0058\u0037\u004d\u0025\u0023\u0079\u005c\u0030\u0037\u002e\u007b\u0026\u0024\u007a\u006f\u0068\u0058\u0051\u0031\u0071\u0075\u0035\u0060\u0022\u0040\u0071\u005b\u004e\u004f\u0043\u006c\u002d\u0051\u0067\u0024\u0026\u0059\u0057\u004b\u0074\u0035\u006a\u002a\u002b\u002d\u005f\u0064\u0027\u0059\u0039\u004b\u0026\u0031\u005d\u0054\u004f\u005a\u0058\u0024\u0047\u0030\u0026\u0060\u002c\u0055\u007e\u005b\u0040\u007d\u0076\u004b\u006a\u003f\u003f\u0076\u0029\u007d\u0031\u0068\u0035\u0020\u0029\u0041\u004c\u002f\u0042\u0069\u0047\u004d\u0048\u004d\u0049\u004c\u0026\u0057\u006c\u0022\u0026\u0023\u006c\u0046\u002e\u0040\u007e\u003c\u0060\u004c\u0060\u0071\u0037\u0078\u004b\u0067\u0032\u0078\u0040\u0056\u0053\u0056\u0035\u0036\u003d\u002d\u0024\u003b\u007b\u0055\u0023\u007a\u0070\u006f\u0078\u0054\u0039